// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Interface IERC20
interface IERC20 {
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

// Interface IERC165
interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

// Interface IERC1363
interface IERC1363 is IERC20, IERC165 {
    function transferAndCall(address to, uint256 value) external returns (bool);
    function transferAndCall(address to, uint256 value, bytes calldata data) external returns (bool);
    function transferFromAndCall(address from, address to, uint256 value) external returns (bool);
    function transferFromAndCall(address from, address to, uint256 value, bytes calldata data) external returns (bool);
    function approveAndCall(address spender, uint256 value) external returns (bool);
    function approveAndCall(address spender, uint256 value, bytes calldata data) external returns (bool);
}

// Library SafeERC20
library SafeERC20 {
    error SafeERC20FailedOperation(address token);
    error SafeERC20FailedDecreaseAllowance(address spender, uint256 currentAllowance, uint256 requestedDecrease);

    function safeTransfer(IERC20 token, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transfer, (to, value)));
    }

    function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

    function trySafeTransfer(IERC20 token, address to, uint256 value) internal returns (bool) {
        return _callOptionalReturnBool(token, abi.encodeCall(token.transfer, (to, value)));
    }

    function trySafeTransferFrom(IERC20 token, address from, address to, uint256 value) internal returns (bool) {
        return _callOptionalReturnBool(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

    function safeIncreaseAllowance(IERC20 token, address spender, uint256 value) internal {
        uint256 oldAllowance = token.allowance(address(this), spender);
        forceApprove(token, spender, oldAllowance + value);
    }

    function safeDecreaseAllowance(IERC20 token, address spender, uint256 requestedDecrease) internal {
        unchecked {
            uint256 currentAllowance = token.allowance(address(this), spender);
            if (currentAllowance < requestedDecrease) {
                revert SafeERC20FailedDecreaseAllowance(spender, currentAllowance, requestedDecrease);
            }
            forceApprove(token, spender, currentAllowance - requestedDecrease);
        }
    }

    function forceApprove(IERC20 token, address spender, uint256 value) internal {
        bytes memory approvalCall = abi.encodeCall(token.approve, (spender, value));
        if (!_callOptionalReturnBool(token, approvalCall)) {
            _callOptionalReturn(token, abi.encodeCall(token.approve, (spender, 0)));
            _callOptionalReturn(token, approvalCall);
        }
    }

    function transferAndCallRelaxed(IERC1363 token, address to, uint256 value, bytes memory data) internal {
        if (to.code.length == 0) {
            safeTransfer(token, to, value);
        } else if (!token.transferAndCall(to, value, data)) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

    function transferFromAndCallRelaxed(
        IERC1363 token,
        address from,
        address to,
        uint256 value,
        bytes memory data
    ) internal {
        if (to.code.length == 0) {
            safeTransferFrom(token, from, to, value);
        } else if (!token.transferFromAndCall(from, to, value, data)) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

    function approveAndCallRelaxed(IERC1363 token, address to, uint256 value, bytes memory data) internal {
        if (to.code.length == 0) {
            forceApprove(token, to, value);
        } else if (!token.approveAndCall(to, value, data)) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

    function _callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }
        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

    function _callOptionalReturnBool(IERC20 token, bytes memory data) private returns (bool) {
        bool success;
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            returnSize := returndatasize()
            returnValue := mload(0)
        }
        return success && (returnSize == 0 ? address(token).code.length > 0 : returnValue == 1);
    }
}

// Interface para Permit2
interface IPermit2 {
    function signatureTransfer(
        IPermit2.PermitTransferFrom memory permit,
        IPermit2.SignatureTransferDetails memory transferDetails,
        address owner,
        bytes calldata signature
    ) external;

    struct PermitTransferFrom {
        address token;
        uint256 amount;
        uint256 nonce;
        uint256 deadline;
    }

    struct SignatureTransferDetails {
        address to;
        uint256 requestedAmount;
    }
}

contract Competition {
    using SafeERC20 for IERC20;

    // Endereço do token WLD
    IERC20 public immutable wldToken;

    // Endereço do Permit2 (endereço padrão na Worldchain)
    IPermit2 public constant PERMIT2 = IPermit2(0x000000000022D473030F116dDEE9F6B43aC78BA3);

    // Taxa mínima e máxima em WLD (considerando 18 decimais)
    uint256 public constant MIN_STAKE = 0.001 ether; // 0.001 WLD
    uint256 public constant MAX_STAKE = 20 ether;     // 20 WLD

    struct Match {
        uint256 id;
        string name;
        address[] participants;
        uint256 stake;
        uint256 startTime;
        uint256 durationDays;
        bool active;
    }

    uint256 public matchCount;
    uint256 public lastMatchIDAdded;
    mapping(uint256 => Match) public matches;

    // ---- Eventos ----
    event MatchCreated(
        uint256 indexed matchId,
        string name,
        uint256 durationDays
    );

    event PlayerJoined(
        uint256 indexed matchId,
        address indexed player
    );

    event MatchClosed(
        uint256 indexed matchId,
        address winner,
        uint256 reward,
        uint256 platformFee
    );


    constructor(address _wldToken) {
        require(_wldToken != address(0), "Invalid WLD token address");
        wldToken = IERC20(_wldToken);
    }

    function createMatch(string memory _name, uint256 _durationDays) external {
        require(_durationDays > 0, "Invalid duration");
        require(bytes(_name).length > 0, "Name cannot be empty");

        matchCount++;
        Match storage m = matches[matchCount];
        m.id = matchCount;
        m.name = _name;
        m.startTime = block.timestamp;
        m.durationDays = _durationDays;
        m.active = true;

        lastMatchIDAdded = matchCount;

        emit MatchCreated(matchCount, _name, _durationDays);
    }

    // Função para participar de uma competição enviando WLD (método tradicional)
    function joinMatch(uint256 _matchId, uint256 _amount) external {
        require(_matchId > 0 && _matchId <= matchCount, "Invalid match ID");
        require(matches[_matchId].active, "Match is not active");
        require(_amount >= MIN_STAKE && _amount <= MAX_STAKE, "Stake must be between 0.001 and 20 WLD");

        // Verificar se o usuário já participou desta competição
        require(!hasParticipated(_matchId, msg.sender), "Already participated in this match");

        // Transferir WLD do usuário para o contrato
        wldToken.safeTransferFrom(msg.sender, address(this), _amount);

        // Adicionar participante à competição
        matches[_matchId].participants.push(msg.sender);
        matches[_matchId].stake += _amount;

        emit PlayerJoined(_matchId, msg.sender);
    }

    // Função para participar usando Permit2 (mais robusta)
    function joinMatchWithPermit2(
        uint256 _matchId,
        uint256 _amount,
        IPermit2.PermitTransferFrom memory _permit,
        IPermit2.SignatureTransferDetails memory _transferDetails,
        bytes calldata _signature
    ) external {
        if (_matchId == 0 || _matchId > matchCount) {
            revert("Invalid match ID");
        }

        if (!matches[_matchId].active) {
            revert("Match is not active");
        }

        if (_amount < MIN_STAKE || _amount > MAX_STAKE) {
            revert("Stake must be between 0.001 and 20 WLD");
        }

        // Verificar se o usuário já participou desta competição
        if (hasParticipated(_matchId, msg.sender)) {
            revert("Already participated in this match");
        }

        // Verificar se o token é WLD
        if (_permit.token != address(wldToken)) {
            revert("Invalid token");
        }

        if (_permit.amount < _amount) {
            revert("Insufficient permit amount");
        }

        // Verificar se o deadline do permit ainda é válido
        if (_permit.deadline < block.timestamp) {
            revert("Permit expired");
        }

        // Verificar se o destinatário da transferência é o contrato
        if (_transferDetails.to != address(this)) {
            revert("Invalid transfer destination");
        }

        if (_transferDetails.requestedAmount != _amount) {
            revert("Amount mismatch");
        }

        // Verificar se o nonce é válido (não foi usado antes)
        if (_permit.nonce == 0) {
            revert("Invalid nonce");
        }

        // Usar Permit2 para transferir tokens
        PERMIT2.signatureTransfer(_permit, _transferDetails, msg.sender, _signature);

        // Adicionar participante à competição
        matches[_matchId].participants.push(msg.sender);
        matches[_matchId].stake += _amount;

        emit PlayerJoined(_matchId, msg.sender);
    }

    // Função auxiliar para verificar se um usuário já participou de uma competição
    function hasParticipated(uint256 _matchId, address _participant) public view returns (bool) {
        require(_matchId > 0 && _matchId <= matchCount, "Invalid match ID");

        address[] memory participants = matches[_matchId].participants;
        for (uint256 i = 0; i < participants.length; i++) {
            if (participants[i] == _participant) {
                return true;
            }
        }
        return false;
    }

    // Função para verificar jogadores e valores investidos na competição
    function getMatchDetails(uint256 _matchId) external view returns (
        uint256 id,
        string memory name,
        address[] memory participants,
        uint256 totalStake,
        uint256 startTime,
        uint256 durationDays,
        bool active
    ) {
        require(_matchId > 0 && _matchId <= matchCount, "Invalid match ID");

        Match storage matchData = matches[_matchId];

        return (
            matchData.id,
            matchData.name,
            matchData.participants,
            matchData.stake,
            matchData.startTime,
            matchData.durationDays,
            matchData.active
        );
    }

}
